/**
 * `agent-sdk migrate` hands an architecture v1 → v2 migration to a Cursor cloud
 * agent. The agent follows the shipped `migrate-v2` skill on the pushed
 * ref and opens a pull request. Nothing is deployed.
 */
import { readFile, readdir } from "node:fs/promises";
import { basename, join, resolve } from "node:path";
import { Agent } from "@cursor/sdk";
import { cloudAgentUrl, resolveApiKey, SIGN_IN_HINT } from "./cursor/credentials.js";
import { httpsGitRepoUrlFromRemote, inferDeployGitSource } from "./deploy-source.js";
import { describeError } from "./describe-error.js";
import { isAgentProjectDir } from "./discovery/project.js";
import { CLI_COMMAND_NAME as CLI, FORMER_PACKAGE_NAME, packageRootDir } from "./distribution.js";
import { parseFrontmatter } from "./frontmatter.js";
import { bindSkillPlaceholders } from "./install-cursor-skills.js";
export async function cmdMigrate(options) {
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    const json = options.json === true;
    const fail = (message) => {
        if (json) {
            out(`${JSON.stringify({ ok: false, error: message }, null, 2)}\n`);
        }
        err(`${message}\n`);
        return 1;
    };
    const dir = resolve(options.dir);
    if (!(await isAgentProjectDir(dir))) {
        return fail(`${dir} is not an Agent SDK project. Pass --dir <project>.`);
    }
    if (!(await sourceNeedsMigration(dir))) {
        const message = nothingToMigrateMessage(options.dir);
        if (json) {
            out(`${JSON.stringify({ ok: true, status: "current", message }, null, 2)}\n`);
        }
        else {
            out(`${message}\n`);
        }
        return 0;
    }
    const inferred = await inferDeployGitSource(dir);
    const remote = options.repo ?? inferred.gitRepoUrl;
    if (remote === undefined) {
        return fail("Could not infer the repository from the origin remote. Pass --repo <https-url>.");
    }
    const repo = httpsGitRepoUrlFromRemote(remote);
    if (repo === undefined) {
        return fail(`--repo ${remote} is not a Git repository URL.`);
    }
    const credential = await resolveApiKey({ apiKey: options.apiKey });
    if (credential === undefined) {
        return fail(`Not signed in to Cursor. ${SIGN_IN_HINT}`);
    }
    const path = options.path ?? inferred.agentPath;
    const ref = options.ref ?? inferred.gitRef;
    if (options.dryRun === true) {
        const plan = { dryRun: true, repo, ref: ref ?? null, path: path ?? null };
        out(json
            ? `${JSON.stringify(plan, null, 2)}\n`
            : `Dry run: would start a Cursor cloud agent that migrates ${path ?? "the repository root"} in ${repo} at ${ref ?? "the default branch"} and opens a pull request. Nothing changed.\n`);
        return 0;
    }
    const checklist = migrationChecklist(options.dir);
    const prompt = migrationPrompt(path, await readMigrationSkill(), path ?? ".");
    let agent;
    let report;
    try {
        agent = await Agent.create({
            apiKey: credential.apiKey,
            name: "Migrate an Agent SDK agent to architecture v2",
            cloud: {
                repos: [{ url: repo, startingRef: ref }],
                autoCreatePR: true,
            },
        });
        const run = await agent.send(prompt);
        if (!json) {
            out(`${checklist}\n`);
        }
        if (options.noWait === true) {
            report = reportFor(agent.agentId, undefined, checklist);
        }
        else {
            if (!json) {
                err(`Migrating ${path ?? "the repository root"} in ${repo} at ${ref ?? "the default branch"}.\n` +
                    `Migration agent started: ${cloudAgentUrl(agent.agentId)}\nWaiting for its pull request.\n`);
            }
            report = reportFor(agent.agentId, await run.wait(), checklist);
        }
    }
    catch (error) {
        if (agent === undefined) {
            return fail(`Could not start the migration agent: ${describeError(error)}`);
        }
        report = {
            ok: false,
            status: "failed",
            agentId: agent.agentId,
            url: cloudAgentUrl(agent.agentId),
            error: `Lost contact with the migration agent; it may still open a pull request. ${describeError(error)}`,
        };
    }
    finally {
        agent?.close();
    }
    out(json ? `${JSON.stringify(report, null, 2)}\n` : render(report));
    return report.ok ? 0 : 1;
}
function migrationPrompt(path, skill, checklistDir) {
    const where = path === undefined ? "the repository root" : `\`${path}\``;
    return [
        `Migrate the Agent SDK project at ${where} from hosted architecture v1 to v2.`,
        "",
        "Follow the skill below from top to bottom, then open one pull request with the migration.",
        "When the skill says to stop or ask, open no pull request and explain what blocks the migration in your final message.",
        'If nothing needs a migration, open no pull request. Your final message must start with "Nothing to migrate." and name the checks you ran.',
        `Do not deploy, run \`${CLI} login\`, or change deployment secrets.`,
        `If the folder has more than one agent, write one \`${CLI} deploy --dir <agent folder>\` command for each agent in the pull request body. Do not deploy.`,
        "Rewrite each MCP connection or peer call whose URL comes from a secret or environment variable that points at another Agent SDK agent.",
        'Do that rewrite in this pull request with `defineConnection({ agent: "<peer-slug>" })`.',
        "When the rewrite succeeds, remove the unused URL secret from code and from `hosting.secretNames`.",
        `List each unused secret in the pull request body for \`${CLI} secret delete\` after deploy.`,
        "When you cannot determine the peer slug, leave a TODO and name it in the pull request body. Do not guess the slug.",
        "Copy the checklist below into the pull request body. Keep the commands. Replace <slug>, <NAME>, and <team-id> when you know the values.",
        "",
        "<checklist>",
        migrationChecklist(checklistDir).trimEnd(),
        "</checklist>",
        "",
        "<skill>",
        skill.trim(),
        "</skill>",
    ].join("\n");
}
async function readMigrationSkill() {
    const root = packageRootDir();
    const raw = await readFile(join(root, "skills", "migrate-v2", "SKILL.md"), "utf8");
    const manifest = JSON.parse(await readFile(join(root, "package.json"), "utf8"));
    const name = manifest !== null &&
        typeof manifest === "object" &&
        "name" in manifest &&
        typeof manifest.name === "string"
        ? manifest.name
        : "";
    const version = manifest !== null &&
        typeof manifest === "object" &&
        "version" in manifest &&
        typeof manifest.version === "string"
        ? manifest.version
        : "";
    if (name.trim() === "" || version.trim() === "") {
        throw new Error("The Agent SDK package must declare a name and a version.");
    }
    return bindSkillPlaceholders(parseFrontmatter(raw).body, name, version);
}
function reportFor(agentId, result, checklist) {
    const url = cloudAgentUrl(agentId);
    if (result === undefined) {
        return { ok: true, status: "running", agentId, url, checklist };
    }
    if (result.status !== "finished") {
        return {
            ok: false,
            status: "failed",
            agentId,
            url,
            error: `Migration agent ended ${result.status}: ${result.error?.message ?? "no details"}`,
        };
    }
    const prUrl = result.git?.branches.find((branch) => branch.prUrl !== undefined)?.prUrl;
    const summary = result.result?.trim();
    if (prUrl === undefined && summary?.startsWith("Nothing to migrate") === true) {
        return { ok: true, status: "current", agentId, url, summary };
    }
    if (prUrl === undefined) {
        return { ok: false, status: "blocked", agentId, url, summary };
    }
    return { ok: true, status: "pr", agentId, url, prUrl, checklist };
}
function render(report) {
    switch (report.status) {
        case "running":
            return `Migration agent started: ${report.url}\n`;
        case "pr":
            return `Pull request: ${report.prUrl}\nReview it and merge. Follow the checklist above after merge.\n`;
        case "current":
            return `${report.summary ?? "Nothing to migrate."}\n\nDetails: ${report.url}\n`;
        case "blocked":
            return `No pull request opened.\n\n${report.summary ?? "The agent gave no reason."}\n\nDetails: ${report.url}\n`;
        case "failed":
            return `${report.error}\nDetails: ${report.url}\n`;
        default: {
            const exhausted = report.status;
            return exhausted;
        }
    }
}
const V1_ARCHITECTURE = /architecture\s*:\s*["']v1["']/;
const GROKBOT_RUNTIME = /runtime\s*:\s*["']grokbot["']/;
const V1_CONTINUATION = /continuation\s*:\s*["'][^"']*\/v1["']/;
const MCP_URL_SECRET = /_MCP_URL\b/;
const STORAGE_FILE = /^storage\.(?:ts|mts|js|mjs)$/;
const SOURCE_FILE = /\.(?:ts|tsx|mts|js|mjs|cjs|jsx)$/;
const SKIP_DIRS = new Set(["node_modules", "dist", "coverage"]);
/**
 * True when the folder still needs a migration, or when the check cannot
 * tell. A clean current project is the only false result. The hosted
 * deployment is not one of these signals.
 */
async function sourceNeedsMigration(dir) {
    if ((await formerPackageSignal(dir)) !== "absent") {
        return true;
    }
    return treeHasMigrationMarker(dir, dir);
}
async function formerPackageSignal(dir) {
    let raw;
    try {
        raw = await readFile(join(dir, "package.json"), "utf8");
    }
    catch (error) {
        return isEnoent(error) ? "absent" : "unreadable";
    }
    let parsed;
    try {
        parsed = JSON.parse(raw);
    }
    catch {
        return "unreadable";
    }
    if (typeof parsed !== "object" || parsed === null) {
        return "unreadable";
    }
    for (const key of [
        "dependencies",
        "devDependencies",
        "optionalDependencies",
        "peerDependencies",
    ]) {
        if (recordHasKey(parsed, key, FORMER_PACKAGE_NAME)) {
            return "present";
        }
    }
    return "absent";
}
function isEnoent(error) {
    return typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
}
async function treeHasMigrationMarker(projectRoot, dir) {
    let entries;
    try {
        entries = await readdir(dir, { withFileTypes: true });
    }
    catch {
        return true;
    }
    for (const entry of entries) {
        if (entry.name.startsWith(".")) {
            continue;
        }
        const path = join(dir, entry.name);
        if (entry.isDirectory()) {
            if (SKIP_DIRS.has(entry.name)) {
                continue;
            }
            if (await treeHasMigrationMarker(projectRoot, path)) {
                return true;
            }
            continue;
        }
        if (!entry.isFile()) {
            continue;
        }
        if (isProjectStorageFile(projectRoot, dir, entry.name)) {
            return true;
        }
        if (!SOURCE_FILE.test(entry.name)) {
            continue;
        }
        let text;
        try {
            text = await readFile(path, "utf8");
        }
        catch {
            return true;
        }
        if (sourceHasMigrationMarker(text)) {
            return true;
        }
    }
    return false;
}
function isProjectStorageFile(projectRoot, dir, name) {
    if (!STORAGE_FILE.test(name)) {
        return false;
    }
    if (dir === projectRoot) {
        return true;
    }
    const parent = basename(dir);
    return (parent === "bot" || parent === "agent") && join(projectRoot, parent) === dir;
}
function sourceHasMigrationMarker(source) {
    return (V1_ARCHITECTURE.test(source) ||
        source.includes(`"${FORMER_PACKAGE_NAME}"`) ||
        source.includes(`'${FORMER_PACKAGE_NAME}'`) ||
        GROKBOT_RUNTIME.test(source) ||
        V1_CONTINUATION.test(source) ||
        MCP_URL_SECRET.test(source) ||
        hasPeerUrlConnection(source) ||
        hasLiteralScmCreds(source) ||
        hasAnonymousReminder(source));
}
function hasPeerUrlConnection(source) {
    if (!source.includes("defineConnection")) {
        return false;
    }
    return /defineConnection\s*\([\s\S]{0,600}?url\s*:\s*process\.env\b/.test(source);
}
function hasLiteralScmCreds(source) {
    if (!/githubChannel|gitlabChannel|bitbucketChannel/.test(source)) {
        return false;
    }
    return (/webhookSecret\s*:\s*(?:\(\)\s*=>|process\.env\b|["'`])/.test(source) ||
        /privateKey\s*:\s*(?:\(\)\s*=>|process\.env\b|["'`])/.test(source) ||
        /appId\s*:\s*(?:\(\)\s*=>|process\.env\b)/.test(source) ||
        /(?:^|[^\w])token\s*:\s*(?:\(\)\s*=>|process\.env\b|["'`])/.test(source));
}
function hasAnonymousReminder(source) {
    if (!/reminders\??\.create\s*\(/.test(source)) {
        return false;
    }
    return (/\brun\s*:\s*(?:async\s*)?(?:\([^)]*\)\s*=>|function\b)/.test(source) ||
        /\buntil\s*:\s*(?:async\s*)?(?:\([^)]*\)\s*=>|function\b)/.test(source));
}
function hasOwnField(value, key) {
    return Object.prototype.hasOwnProperty.call(value, key);
}
function recordHasKey(value, key, name) {
    if (!hasOwnField(value, key)) {
        return false;
    }
    const field = value[key];
    return (typeof field === "object" && field !== null && Object.prototype.hasOwnProperty.call(field, name));
}
function nothingToMigrateMessage(dir) {
    const folder = commandDir(dir);
    return [
        "Nothing to migrate.",
        `Checked ${folder}: no ${FORMER_PACKAGE_NAME} dependency, no architecture: "v1", no storage.ts, no runtime: "grokbot", no literal SCM credential, no /v1 continuation, no anonymous reminder, and no *_MCP_URL peer.`,
        "No migration agent was started.",
        `This command does not check the hosted deployment. If \`${CLI} deployment get <slug>\` does not print architecture: v2, run \`${CLI} deploy --dir ${folder}\`.`,
    ].join("\n");
}
function migrationChecklist(dir) {
    const folder = commandDir(dir);
    return [
        "After merge, deploy from the merged ref. This migration does not deploy and does not change secrets.",
        "",
        "Deploy each agent. One command per folder. Do not use deploy --all.",
        `  ${CLI} deploy --dir ${folder}`,
        "",
        "Slack. Log in as a person. The server redeploys by itself. Uninstall the old app and invite the new bot to the old channels.",
        `  ${CLI} slack create --prod --dir ${folder} [--team <team-id>]`,
        "",
        "Peers. Deploy both agents before you use defineConnection. Unset each peer URL secret the pull request lists.",
        `  ${CLI} secret delete <slug> <NAME>`,
        "",
        "Secrets. Same-slug deploy copies v1 secrets. A new slug needs secrets set. No redeploy after secrets set.",
        `  ${CLI} secret list <slug> [--team <team-id>]`,
        `  ${CLI} secret set <slug> <NAME>`,
    ].join("\n");
}
function commandDir(dir) {
    if (/^[A-Za-z0-9_./@+-]+$/.test(dir)) {
        return dir;
    }
    return `'${dir.replaceAll("'", `'\\''`)}'`;
}
